from scipy.optimize import least_squares
forms={
 'mult_poly_exp': lambda p: (p[0]+p[1]*P+p[2]*P**2+p[3]/P)*np.exp(p[4]*t)+p[5]*P,
 'logistic_Kt': lambda p: p[0]*P*(1-P/(p[1]+p[2]*t))+p[3]*P+p[4]*t*P,
 'harv_t': lambda p: p[0]*P*(1-P/p[1]) - p[2]*P*(1+p[3]*np.sin(p[4]*t+p[5])) + p[6],
 'allee': lambda p: p[0]*P*(P/p[1]-1)*(1-P/p[2]) - p[3]*t + p[4],
 'pow_t': lambda p: (p[0]+p[1]*P+p[2]/P)*(t**p[3]) + p[4]*P**2,
 'mix': lambda p: p[0]*P+p[1]*P**2+p[2]/P+p[3]*t*P**2+p[4]*t+p[5]*t**2*P+p[6]*np.log(t)+p[7],
}
rng=np.random.default_rng(0)
for k,f in forms.items():
    best=None
    for trial in range(25):
        p0=rng.normal(0,1,10)
        try:
            r=least_squares(lambda p: f(p)-dP_dt, p0[:9] if k not in('harv_t','mix') else p0[:9], max_nfev=2000)
